True from collections import Counter

def transform(grid):
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [i for i, row in enumerate(grid) if any(v != background for v in row)]
    groups = []
    for r in active:
        if not groups or r != groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)

    pairs = []
    if len(groups) == 2 and len(groups[0]) == len(groups[1]):
        pairs = list(zip(groups[0], groups[1]))
    for a, b in pairs:
        for r, ref in ((a, b), (b, a)):
            k = len(grid[r])
            while k and grid[r][k - 1] == background:
                k -= 1
            if k < len(grid[r]):
                for c in range(k, len(grid[r])):
                    if grid[ref][c] != background and grid[r][c] == background:
                        out[r][c] = 1
    if not pairs:
        for r in active:
            k = len(grid[r])
            while k and grid[r][k - 1] == background:
                k -= 1
            if k == len(grid[r]):
                continue
            refs = [q for q in active if q != r]
            if refs:
                ref = max(refs, key=lambda q: sum(grid[q][c] != background for c in range(k, len(grid[r]))))
                for c in range(k, len(grid[r])):
                    if grid[r][c] == background and grid[ref][c] != background:
                        out[r][c] = 1
    return out
